import {
	fetchPrivateMessageSubscriptionStatus,
	recordPrivateMessageSubscriptionGrant
} from '../api/message';

export const PRIVATE_MESSAGE_TEMPLATE_ID = 'EahPbaBY9kOjt0Y-HHFq9SOrsNhG-VzpZVP52hDGX4U';

const PENDING_GRANT_STORAGE_KEY = 'private_message_subscription_pending_grants';
const MAX_PENDING_GRANTS = 10;
let syncPromise = null;

function readPendingGrantCount() {
	try {
		return Math.max(0, Math.min(MAX_PENDING_GRANTS, Number(uni.getStorageSync(PENDING_GRANT_STORAGE_KEY) || 0)));
	} catch (error) {
		return 0;
	}
}

function writePendingGrantCount(count) {
	try {
		const normalized = Math.max(0, Math.min(MAX_PENDING_GRANTS, Number(count || 0)));
		if (normalized) uni.setStorageSync(PENDING_GRANT_STORAGE_KEY, normalized);
		else uni.removeStorageSync(PENDING_GRANT_STORAGE_KEY);
	} catch (error) {}
}

function addPendingGrant() {
	writePendingGrantCount(readPendingGrantCount() + 1);
}

export function syncPendingPrivateMessageGrants() {
	if (syncPromise) return syncPromise;
	syncPromise = (async () => {
		let pendingCount = readPendingGrantCount();
		while (pendingCount > 0) {
			await recordPrivateMessageSubscriptionGrant(PRIVATE_MESSAGE_TEMPLATE_ID);
			pendingCount -= 1;
			writePendingGrantCount(pendingCount);
		}
	})().finally(() => {
		syncPromise = null;
	});
	return syncPromise;
}

export async function loadPrivateMessageSubscriptionStatus() {
	try {
		await syncPendingPrivateMessageGrants();
	} catch (error) {}
	return fetchPrivateMessageSubscriptionStatus();
}

export function requestPrivateMessageSubscription() {
	return new Promise((resolve, reject) => {
		if (typeof uni.requestSubscribeMessage !== 'function') {
			const error = new Error('当前环境不支持订阅消息。');
			error.unsupported = true;
			reject(error);
			return;
		}

		uni.requestSubscribeMessage({
			tmplIds: [PRIVATE_MESSAGE_TEMPLATE_ID],
			success: async (result = {}) => {
				const decision = result[PRIVATE_MESSAGE_TEMPLATE_ID];
				if (decision !== 'accept') {
					resolve({ accepted: false, decision: decision || 'reject' });
					return;
				}

				addPendingGrant();
				try {
					await syncPendingPrivateMessageGrants();
					const status = await fetchPrivateMessageSubscriptionStatus();
					resolve({ accepted: true, status });
				} catch (error) {
					error.subscriptionAccepted = true;
					reject(error);
				}
			},
			fail: (error) => reject(error)
		});
	});
}
